import{_ as t,c as d,o,a5 as n}from"./chunks/framework.CUJoMJm2.js";const p=JSON.parse('{"title":"Sideband Relay Protocol State Machine","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/sbrp/state-machine.md","filePath":"protocols/sbrp/state-machine.md","lastUpdated":1768070912000}'),a={name:"protocols/sbrp/state-machine.md"};function s(r,e,i,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[n('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/sbrp/state-machine.md for this page in Markdown format</div><h1 id="sideband-relay-protocol-state-machine" tabindex="-1">Sideband Relay Protocol State Machine <a class="header-anchor" href="#sideband-relay-protocol-state-machine" aria-label="Permalink to “Sideband Relay Protocol State Machine”">​</a></h1><blockquote><p><strong>Authority</strong>: Primary (Normative)<br><strong>Purpose</strong>: State transitions, lifecycle semantics, and control code behavioral definitions.</p></blockquote><p>Concise state models for Client, Daemon, and Relay sessions. Intended to complement the <a href="./">main SBRP spec</a> with implementer-facing control flow.</p><h2 id="notation" tabindex="-1">Notation <a class="header-anchor" href="#notation" aria-label="Permalink to “Notation”">​</a></h2><ul><li>Event names are in <code>code</code> format.</li><li>Transitions list the next state and key requirements.</li><li>Error transitions terminate the session unless otherwise noted.</li><li>Control codes reference §14 of the main spec.</li></ul><h2 id="control-code-quick-reference" tabindex="-1">Control Code Quick Reference <a class="header-anchor" href="#control-code-quick-reference" aria-label="Permalink to “Control Code Quick Reference”">​</a></h2><blockquote><p><strong>Note</strong>: This table is a non-authoritative snapshot for quick reference. For canonical code values, see <a href="./control-codes">control-codes.md</a>.</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:right;">Code</th><th>Name</th><th>T/N</th><th>SID</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0x0101</td><td>unauthorized</td><td>T</td><td>0</td><td>Invalid/expired token</td></tr><tr><td style="text-align:right;">0x0102</td><td>forbidden</td><td>T</td><td>0</td><td>Access denied</td></tr><tr><td style="text-align:right;">0x0201</td><td>daemon_not_found</td><td>T</td><td>S</td><td>Unknown daemon ID</td></tr><tr><td style="text-align:right;">0x0202</td><td>daemon_offline</td><td>N</td><td>S</td><td>Daemon not connected</td></tr><tr><td style="text-align:right;">0x0301</td><td>session_not_found</td><td>T</td><td>S</td><td>Unknown session ID</td></tr><tr><td style="text-align:right;">0x0302</td><td>session_expired</td><td>T</td><td>S</td><td>Session terminated</td></tr><tr><td style="text-align:right;">0x0401</td><td>malformed_frame</td><td>T</td><td>0</td><td>Invalid header</td></tr><tr><td style="text-align:right;">0x0402</td><td>payload_too_large</td><td>T</td><td>0</td><td>Exceeds 64KB</td></tr><tr><td style="text-align:right;">0x0403</td><td>invalid_frame_type</td><td>T</td><td>0</td><td>Unknown type byte</td></tr><tr><td style="text-align:right;">0x0404</td><td>invalid_session_id</td><td>T</td><td>0</td><td>SessionID invalid</td></tr><tr><td style="text-align:right;">0x0405</td><td>disallowed_sender</td><td>T</td><td>S</td><td>Wrong direction</td></tr><tr><td style="text-align:right;">0x0601</td><td>internal_error</td><td>T</td><td>0</td><td>Relay internal failure</td></tr><tr><td style="text-align:right;">0x0901</td><td>rate_limited</td><td>N</td><td>0</td><td>Too many requests</td></tr><tr><td style="text-align:right;">0x1001</td><td>session_paused</td><td>N</td><td>S</td><td>Daemon disconnected</td></tr><tr><td style="text-align:right;">0x1002</td><td>session_resumed</td><td>N</td><td>S</td><td>Daemon ready</td></tr><tr><td style="text-align:right;">0x1003</td><td>session_ended</td><td>N</td><td>S</td><td>Client disconnected</td></tr><tr><td style="text-align:right;">0x1004</td><td>session_pending</td><td>N</td><td>S</td><td>Awaiting daemon ready</td></tr></tbody></table><h2 id="client-ui" tabindex="-1">Client (UI) <a class="header-anchor" href="#client-ui" aria-label="Permalink to “Client (UI)”">​</a></h2><p>States focus on a single daemon connection.</p><table tabindex="0"><thead><tr><th>State</th><th>Event</th><th>Next</th><th>Notes</th></tr></thead><tbody><tr><td><code>Idle</code></td><td><code>connect</code></td><td><code>Connecting</code></td><td>Open WebSocket to relay with session token.</td></tr><tr><td><code>Connecting</code></td><td><code>ws_open</code></td><td><code>Handshaking</code></td><td>Send <code>HandshakeInit</code> with client ephemeral key.</td></tr><tr><td><code>Connecting</code></td><td><code>ws_error</code></td><td><code>Closed</code></td><td>Surface transport error.</td></tr><tr><td><code>Handshaking</code></td><td><code>HandshakeAccept</code></td><td><code>Active</code></td><td>Verify Ed25519 signature using pinned identity key; derive session keys.</td></tr><tr><td><code>Handshaking</code></td><td><code>identity_key_changed</code></td><td><code>Closed</code></td><td>MUST abort; require explicit user confirmation to accept new key.</td></tr><tr><td><code>Handshaking</code></td><td><code>handshake_failed</code></td><td><code>Closed</code></td><td>Abort; discard ephemeral key material.</td></tr><tr><td><code>Active</code></td><td><code>Control(session_paused)</code></td><td><code>Paused</code></td><td>Keep WebSocket open; suspend encrypted sends.</td></tr><tr><td><code>Active</code></td><td><code>Control(session_expired)</code></td><td><code>Reconnecting</code></td><td>Session ended (state lost or grace expired); trigger full handshake.</td></tr><tr><td><code>Active</code></td><td><code>ws_close</code></td><td><code>Reconnecting</code></td><td>Client reconnect always requires full handshake.</td></tr><tr><td><code>Paused</code></td><td><code>Control(session_pending)</code></td><td><code>Pending</code></td><td>Daemon reconnected; await Signal(ready) or Signal(close).</td></tr><tr><td><code>Paused</code></td><td><code>Control(session_expired)</code></td><td><code>Reconnecting</code></td><td>Trigger full handshake (new ephemeral keys).</td></tr><tr><td><code>Pending</code></td><td><code>Control(session_resumed)</code></td><td><code>Active</code></td><td>Resume with same session keys and sequence state.</td></tr><tr><td><code>Pending</code></td><td><code>Control(session_expired)</code></td><td><code>Reconnecting</code></td><td>Daemon sent Signal(close); trigger full handshake.</td></tr><tr><td><code>Reconnecting</code></td><td><code>ws_open</code></td><td><code>Handshaking</code></td><td>New session token required (new <code>sid</code>); generate new ephemeral keys.</td></tr><tr><td><code>Reconnecting</code></td><td><code>ws_error</code></td><td><code>Closed</code></td><td>Surface transport error.</td></tr><tr><td><code>Active</code></td><td><code>close</code></td><td><code>Closed</code></td><td>User-initiated disconnect.</td></tr></tbody></table><h2 id="daemon-agent" tabindex="-1">Daemon (Agent) <a class="header-anchor" href="#daemon-agent" aria-label="Permalink to “Daemon (Agent)”">​</a></h2><p>States focus on a single client session; daemons may have many in parallel.</p><table tabindex="0"><thead><tr><th>State</th><th>Event</th><th>Next</th><th>Notes</th></tr></thead><tbody><tr><td><code>Idle</code></td><td><code>register</code></td><td><code>Registered</code></td><td>Create identity keypair; register via control plane.</td></tr><tr><td><code>Registered</code></td><td><code>connect</code></td><td><code>Connected</code></td><td>Open persistent WebSocket to relay with presence token.</td></tr><tr><td><code>Connected</code></td><td><code>HandshakeInit</code></td><td><code>Handshaking</code></td><td>Generate ephemeral X25519 and sign with identity key.</td></tr><tr><td><code>Handshaking</code></td><td><code>HandshakeAccept_sent</code></td><td><code>Active</code></td><td>Derive session keys; init sequence state.</td></tr><tr><td><code>Active</code></td><td><code>Control(session_ended)</code></td><td><code>Idle</code></td><td>Per-session cleanup only; relay signals client disconnect.</td></tr><tr><td><code>Active</code></td><td><code>ws_close</code></td><td><code>Reconnecting</code></td><td>Attempt reconnect using presence token.</td></tr><tr><td><code>Reconnecting</code></td><td><code>ws_open_within_grace</code></td><td><code>Connected</code></td><td>Check state for each session; send <code>Signal(ready)</code> or <code>Signal(close)</code> per session.</td></tr><tr><td><code>Reconnecting</code></td><td><code>ws_open_after_grace</code></td><td><code>Connected</code></td><td>Start new sessions; old session state is dropped.</td></tr><tr><td><code>Connected</code></td><td><code>state_retained</code></td><td><code>Active</code></td><td>Per-session: send <code>Signal(ready)</code>; resume with retained keys, seq counters, replay window.</td></tr><tr><td><code>Connected</code></td><td><code>state_lost</code></td><td><code>Connected</code></td><td>Per-session: send <code>Signal(close, reason=state_lost)</code>; await new <code>HandshakeInit</code> from client.</td></tr><tr><td><code>Connected</code></td><td><code>close</code></td><td><code>Closed</code></td><td>Tear down relay connection.</td></tr></tbody></table><h2 id="relay-per-session-pair" tabindex="-1">Relay (Per-Session Pair) <a class="header-anchor" href="#relay-per-session-pair" aria-label="Permalink to “Relay (Per-Session Pair)”">​</a></h2><p>A relay tracks the pairing between one client connection and one daemon connection.</p><table tabindex="0"><thead><tr><th>State</th><th>Event</th><th>Next</th><th>Notes</th></tr></thead><tbody><tr><td><code>None</code></td><td><code>client_ws_open</code></td><td><code>ClientOnly</code></td><td>Validate session token; await pairing.</td></tr><tr><td><code>None</code></td><td><code>daemon_ws_open</code></td><td><code>DaemonOnly</code></td><td>Validate presence token; mark daemon online.</td></tr><tr><td><code>ClientOnly</code></td><td><code>daemon_ws_open</code></td><td><code>Paired</code></td><td>Bind client to daemon; forward handshake messages.</td></tr><tr><td><code>DaemonOnly</code></td><td><code>client_ws_open</code></td><td><code>Paired</code></td><td>Bind client to daemon; forward handshake messages.</td></tr><tr><td><code>Paired</code></td><td><code>daemon_ws_close</code></td><td><code>Paused</code></td><td>Send <code>Control(session_paused)</code> to client; pause routing.</td></tr><tr><td><code>Paired</code></td><td><code>Signal(close)</code></td><td><code>Closed</code></td><td>Daemon lost state; send <code>Control(session_expired)</code> to client; close pairing.</td></tr><tr><td><code>Paused</code></td><td><code>daemon_ws_open(res=false)</code></td><td><code>Closed</code></td><td>Non-resumable daemon; send <code>Control(session_expired)</code> to client immediately.</td></tr><tr><td><code>Paused</code></td><td><code>daemon_ws_open_within_grace</code></td><td><code>Pending</code></td><td>Resumable daemon reconnected; send <code>Control(session_pending)</code> to client; await Signal.</td></tr><tr><td><code>Paused</code></td><td><code>client_ws_close</code></td><td><code>Closed</code></td><td>Client disconnected while paused; tear down pairing (no notification).</td></tr><tr><td><code>Paused</code></td><td><code>grace_expired</code></td><td><code>Closed</code></td><td>Send <code>Control(session_expired)</code> to client; close WebSocket.</td></tr><tr><td><code>Pending</code></td><td><code>Signal(ready)</code></td><td><code>Paired</code></td><td>Send <code>Control(session_resumed)</code> to client; resume routing.</td></tr><tr><td><code>Pending</code></td><td><code>Signal(close)</code></td><td><code>Closed</code></td><td>Daemon lost state; send <code>Control(session_expired)</code> to client; close pairing.</td></tr><tr><td><code>Pending</code></td><td><code>client_ws_close</code></td><td><code>Closed</code></td><td>Client disconnected; send <code>Control(session_ended)</code> to daemon.</td></tr><tr><td><code>Pending</code></td><td><code>grace_expired</code></td><td><code>Closed</code></td><td>Timeout waiting for daemon signal; send <code>Control(session_expired)</code>.</td></tr><tr><td><code>Paired</code></td><td><code>client_ws_close</code></td><td><code>Closed</code></td><td>Send <code>Control(session_ended)</code> to daemon; tear down pairing.</td></tr></tbody></table><h2 id="required-invariants" tabindex="-1">Required Invariants <a class="header-anchor" href="#required-invariants" aria-label="Permalink to “Required Invariants”">​</a></h2><ul><li>No encrypted traffic before <code>Active</code> is reached.</li><li>Client MUST obtain a new session token (new <code>sid</code>) on reconnect; no client-side session resumption.</li><li>Handshake SHOULD complete within 30 seconds; timeout triggers <code>handshake_failed</code>.</li><li>Ping/Pong frames are connection-scoped (SessionID = 0) and never forwarded.</li><li>Relay MUST respond to Ping with Pong, copying payload.</li></ul><h3 id="resumable-daemons-default-res-claim-absent-or-true" tabindex="-1">Resumable Daemons (default, <code>res</code> claim absent or <code>true</code>) <a class="header-anchor" href="#resumable-daemons-default-res-claim-absent-or-true" aria-label="Permalink to “Resumable Daemons (default, res claim absent or true)”">​</a></h3><ul><li>A resumed session MUST reuse the same session keys and sequence state.</li><li>After reconnect, daemon MUST send <code>Signal(ready)</code> for sessions with retained state, <code>Signal(close, reason=state_lost)</code> for sessions with lost state.</li><li>Relay MUST send <code>Control(session_pending)</code> to client when daemon reconnects.</li><li>Relay MUST NOT send <code>Control(session_resumed)</code> until daemon sends <code>Signal(ready)</code>.</li><li>If sequence state is lost (even partially), daemon MUST send <code>Signal(close, reason=state_lost)</code> for that session before processing frames.</li><li>If the daemon process restarts or loses volatile memory, it MUST send <code>Signal(close, reason=state_lost)</code> for all sessions.</li></ul><h3 id="state-integrity-verification" tabindex="-1">State Integrity Verification <a class="header-anchor" href="#state-integrity-verification" aria-label="Permalink to “State Integrity Verification”">​</a></h3><p>Before sending <code>Signal(ready)</code> for a session, the daemon MUST verify that all required per-session state is present, well-formed, and internally consistent. If verification fails, daemon MUST send <code>Signal(close, reason=state_lost)</code> for that session.</p><p><strong>Required components</strong> (per <a href="./cryptography-and-wire">cryptography-and-wire.md</a>):</p><ul><li>Session ID</li><li>Directional traffic keys (<code>clientToDaemon</code>, <code>daemonToClient</code>)</li><li>Send sequence number</li><li>Receive replay state (<code>maxSeen</code> and bitmap)</li></ul><p><strong>Verification requirements:</strong></p><ol><li>All components MUST be present</li><li>Keys MUST be correct length (32 bytes each)</li><li>Sequence numbers MUST be valid (non-negative, not exhausted)</li><li>Replay window MUST be consistent with <code>maxSeen</code></li></ol><p>If any check fails → <code>Signal(close, reason=state_lost)</code> for that session. If all checks pass → <code>Signal(ready)</code> for that session.</p><div class="tip custom-block"><p class="custom-block-title">Implementation Note</p><p>For in-memory state (the common case), verification requires checking that:</p><ol><li>The session object exists with all fields populated</li><li>Key lengths are correct (32 bytes each)</li><li>Sequence numbers are valid and not exhausted</li><li>Replay window is consistent with <code>maxSeen</code></li></ol><p>Merely confirming field presence is necessary but not sufficient. Daemons that do not persist session state across process restarts will fail these checks on restart and MUST close all sessions.</p><p>For daemons that persist state to durable storage, implementations SHOULD add an integrity check (e.g., HMAC or authenticated encryption) to detect corruption or tampering during storage.</p></div><h3 id="non-resumable-daemons-res-false" tabindex="-1">Non-Resumable Daemons (<code>res: false</code>) <a class="header-anchor" href="#non-resumable-daemons-res-false" aria-label="Permalink to “Non-Resumable Daemons (res: false)”">​</a></h3><ul><li>Relay MUST send <code>Control(session_expired)</code> to all paired clients immediately upon daemon reconnect.</li><li>Daemon need not track session IDs or send Signal frames.</li></ul><h3 id="relay-routing-rules-frame-authority" tabindex="-1">Relay Routing Rules (Frame Authority) <a class="header-anchor" href="#relay-routing-rules-frame-authority" aria-label="Permalink to “Relay Routing Rules (Frame Authority)”">​</a></h3><table tabindex="0"><thead><tr><th>Frame Type</th><th>Client Can Send</th><th>Daemon Can Send</th><th>Relay Action</th></tr></thead><tbody><tr><td>HandshakeInit</td><td>✓</td><td>✗</td><td>Forward to daemon</td></tr><tr><td>HandshakeAccept</td><td>✗</td><td>✓</td><td>Forward to client</td></tr><tr><td>Data</td><td>✓</td><td>✓</td><td>Forward to peer</td></tr><tr><td>Signal</td><td>✗</td><td>✓</td><td>Process (ready/close)</td></tr><tr><td>Ping</td><td>✓</td><td>✓</td><td>Respond with Pong locally</td></tr><tr><td>Pong</td><td>✓</td><td>✓</td><td>Process locally</td></tr><tr><td>Control</td><td>✗</td><td>✗</td><td>Relay generates only</td></tr></tbody></table><p>Relay MUST validate frames in order per §13.3 (header parse → payload size → frame type → SessionID validity → direction) and return the first matching error.</p>',35)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
